/**
 * argparse.mjs — a faithful, minimal port of CPython's `argparse`, covering
 * exactly the surface that `test7.py` uses:
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--key', type=str, required=True)
 *     ... (--iv, --data1, --data2)
 *     args = parser.parse_args()
 *
 * Everything here was derived from, and byte-verified against, the frozen
 * CPython oracle (`test7_executable`): the help/usage layout (including the
 * terminal-width dependent wrapping), the error message templates, the
 * abbreviation and `--`/`=`/short-bundling rules, and the error precedence.
 *
 * Only `node:` built-ins are used. No external dependencies.
 */

import process from 'node:process';
import { basename } from 'node:path';
import { Buffer } from 'node:buffer';
import { writeSync } from 'node:fs';

/** argparse's `prefix_chars` default. */
const PREFIX_CHARS = '-';

/** Sentinel mirroring `argparse.SUPPRESS` (used for the help action default). */
const SUPPRESS = Symbol('SUPPRESS');

/** `HelpFormatter(indent_increment=2)`, applied once for the options section. */
const HELP_INDENT = 2;

/** `HelpFormatter(max_help_position=24)`. */
const MAX_HELP_POSITION = 24;

/** Exit status `ArgumentParser.error()` uses. */
const EXIT_ARG_ERROR = 2;

/**
 * `argparse._negative_number_matcher`, i.e. `re.compile(r'^-\d+$|^-\d*\.\d+$')`.
 * Two Python-isms are reproduced deliberately:
 *   - `\d` is the Unicode `Nd` category, not `[0-9]`, so `-٥` is a number;
 *   - `$` also matches immediately before a single trailing newline, so
 *     `'-5\n'` matches while `'-5\n\n'` and `'-5\nx'` do not.
 * Both were confirmed against the oracle.
 */
const NEGATIVE_NUMBER_MATCHER = /^-\p{Nd}+\n?$|^-\p{Nd}*\.\p{Nd}+\n?$/u;

/**
 * `argparse.HelpFormatter._format_usage`'s `part_regexp`: usage strings are
 * broken into wrappable parts that keep bracketed/parenthesised groups whole.
 */
const USAGE_PART_MATCHER = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

/** `argparse.HelpFormatter._whitespace_matcher`. */
const WHITESPACE_MATCHER = /\s+/g;

/** `argparse.HelpFormatter._long_break_matcher`. */
const LONG_BREAK_MATCHER = /\n\n\n+/g;

// ---------------------------------------------------------------------------
// Low-level output
// ---------------------------------------------------------------------------

/**
 * Write `text` to a file descriptor synchronously and completely.
 *
 * Node's `process.stdout.write()` is asynchronous on pipes, so a following
 * `process.exit()` can truncate it. CPython's `sys.exit()` flushes, so the
 * port writes through `fs.writeSync` to get the same guarantee.
 */
function writeAllSync(fd, text) {
  const buf = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buf.length) {
    try {
      offset += writeSync(fd, buf, offset, buf.length - offset);
    } catch (err) {
      // A non-blocking pipe can refuse the write; retry as CPython's
      // buffered writer effectively does.
      if (err.code !== 'EAGAIN') throw err;
    }
  }
}

// ---------------------------------------------------------------------------
// Python helpers
// ---------------------------------------------------------------------------

/**
 * `repr()` of a Python `str`, needed for the `%r` in argparse's
 * "ignored explicit argument %r" message.
 *
 * Quote selection and the ASCII escape set match CPython exactly (verified:
 * `it's` -> `"it's"`, `both'and"` -> `'both\'and"'`, `tab\there` ->
 * `'tab\there'`). Code points above U+00A0 are emitted verbatim, which is
 * correct for every printable character; CPython additionally escapes
 * non-printable astral/format characters, which cannot occur in the option
 * tails that reach this message in practice.
 */
function pythonStrRepr(str) {
  const quote = str.includes("'") && !str.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of str) {
    const code = ch.codePointAt(0);
    if (ch === quote || ch === '\\') out += '\\' + ch;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (code < 0x20 || code === 0x7f || (code >= 0x80 && code <= 0xa0)) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else out += ch;
  }
  return out + quote;
}

/** `int(os.environ['COLUMNS'])` semantics: a plain, optionally signed integer. */
function parsePythonInt(text) {
  const trimmed = text.trim();
  return /^[+-]?[0-9]+$/.test(trimmed) ? Number.parseInt(trimmed, 10) : null;
}

/**
 * `shutil.get_terminal_size().columns`: `$COLUMNS` if it parses as a positive
 * integer, else the tty width of stdout, else the 80-column fallback.
 */
function terminalColumns() {
  const env = process.env.COLUMNS;
  if (env !== undefined) {
    const columns = parsePythonInt(env);
    if (columns !== null && columns > 0) return columns;
  }
  const stdout = process.stdout;
  if (stdout && stdout.isTTY && stdout.columns > 0) return stdout.columns;
  return 80;
}

/**
 * `textwrap.wrap()` for the whitespace-normalised, hyphen-free help strings
 * this parser formats: a greedy fill, which is what textwrap reduces to when
 * no word exceeds the line width.
 */
function wrapText(text, width) {
  const lines = [];
  let line = '';
  for (const word of text.split(' ')) {
    if (word === '') continue;
    if (line === '') line = word;
    else if (line.length + 1 + word.length <= width) line += ' ' + word;
    else {
      lines.push(line);
      line = word;
    }
  }
  if (line !== '') lines.push(line);
  return lines;
}

/** `str.strip('\n')` followed by a single trailing newline. */
function normalizeHelpTail(text) {
  return text.replace(/^\n+/, '').replace(/\n+$/, '') + '\n';
}

// ---------------------------------------------------------------------------
// Actions and errors
// ---------------------------------------------------------------------------

/** One `argparse.Action`: an option string group plus how it consumes values. */
class Action {
  constructor({ optionStrings, dest, nargs, required, help, metavar, type, isHelp }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
    this.type = type;
    this.isHelp = isHelp;
    this.default = isHelp ? SUPPRESS : null;
  }

  /** `argparse._get_action_name`: the name used in every error message. */
  get canonicalName() {
    return this.optionStrings.join('/');
  }

  /** `HelpFormatter._get_default_metavar_for_optional` / `_metavar_formatter`. */
  get metavarText() {
    return this.metavar !== undefined ? this.metavar : this.dest.toUpperCase();
  }
}

/** `argparse.ArgumentError`, whose `str()` prefixes the offending option. */
class ArgumentError extends Error {
  constructor(action, message) {
    super(action === null ? message : `argument ${action.canonicalName}: ${message}`);
    this.name = 'ArgumentError';
  }
}

/** Thrown by the help action so `parseArgs` can exit after printing help. */
class ExitParser extends Error {
  constructor(status, message) {
    super('exit');
    this.name = 'ExitParser';
    this.status = status;
    this.stream = message;
  }
}

// ---------------------------------------------------------------------------
// ArgumentParser
// ---------------------------------------------------------------------------

export class ArgumentParser {
  /**
   * @param {{prog?: string, addHelp?: boolean}} [options]
   *   `prog` defaults to `os.path.basename(sys.argv[0])`'s analogue,
   *   `basename(process.argv[1])`.
   */
  constructor(options = {}) {
    this.prog = options.prog !== undefined
      ? options.prog
      : basename(process.argv[1] === undefined ? '' : process.argv[1]);
    /** @type {Action[]} — declaration order drives every message's ordering. */
    this._actions = [];
    /** @type {Map<string, Action>} — insertion-ordered option string table. */
    this._optionStringActions = new Map();

    if (options.addHelp !== false) {
      this.addArgument(['-h', '--help'], {
        nargs: 0,
        isHelp: true,
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * `ArgumentParser.add_argument()` for optionals.
   *
   * @param {string|string[]} flags one or more option strings, e.g. '--key'.
   * @param {{type?: Function, required?: boolean, help?: string, dest?: string,
   *          metavar?: string, nargs?: number, isHelp?: boolean}} [opts]
   */
  addArgument(flags, opts = {}) {
    const optionStrings = Array.isArray(flags) ? flags.slice() : [flags];
    if (optionStrings.length === 0) throw new Error('addArgument needs an option string');

    // argparse derives dest from the first long option string, stripping
    // leading prefix chars and turning inner dashes into underscores.
    let dest = opts.dest;
    if (dest === undefined) {
      const long = optionStrings.find((s) => s.startsWith('--'));
      dest = (long === undefined ? optionStrings[0] : long)
        .replace(/^-+/, '')
        .replace(/-/g, '_');
    }

    const action = new Action({
      optionStrings,
      dest,
      nargs: opts.nargs === undefined ? null : opts.nargs, // null == argparse's nargs=None
      required: opts.required === true,
      help: opts.help,
      metavar: opts.metavar,
      type: opts.type,
      isHelp: opts.isHelp === true,
    });

    this._actions.push(action);
    for (const optionString of optionStrings) this._optionStringActions.set(optionString, action);
    return action;
  }

  // -- help / usage formatting ---------------------------------------------

  /** `ArgumentParser.format_usage()`: the usage block with one trailing newline. */
  formatUsage() {
    return normalizeHelpTail(this._formatUsage(terminalColumns() - 2));
  }

  /** `ArgumentParser.format_help()`: the full help text, one trailing newline. */
  formatHelp() {
    const width = terminalColumns() - 2;
    // HelpFormatter.__init__ clamps max_help_position for narrow terminals.
    const maxHelpPosition = Math.min(MAX_HELP_POSITION, Math.max(width - 20, HELP_INDENT * 2));
    // action_max_length is the widest invocation plus the section indent.
    const actionMaxLength = Math.max(
      ...this._actions.map((a) => this._formatActionInvocation(a).length + HELP_INDENT),
    );
    const helpPosition = Math.min(actionMaxLength + 2, maxHelpPosition);

    const parts = [this._formatUsage(width), '\n', 'options:\n'];
    for (const action of this._actions) {
      parts.push(this._formatAction(action, width, helpPosition));
    }
    parts.push('\n');
    return normalizeHelpTail(parts.join('').replace(LONG_BREAK_MATCHER, '\n\n'));
  }

  /** `HelpFormatter._format_usage`; returns the raw block ending in '\n\n'. */
  _formatUsage(width) {
    const prefix = 'usage: ';
    const actionUsage = this._actions.map((a) => this._formatActionUsagePart(a)).join(' ');
    const oneLine = [this.prog, actionUsage].filter((s) => s !== '').join(' ');
    const textWidth = width; // _width minus a zero _current_indent

    if (prefix.length + oneLine.length <= textWidth) return `${prefix}${oneLine}\n\n`;

    const parts = actionUsage.match(USAGE_PART_MATCHER) || [];

    // Wrap `parts` onto lines of at most `textWidth`, prefixing each with
    // `indent`. With `prefix` given, the first line's budget starts after the
    // prefix and its indent is stripped (the caller prepends the prefix).
    const getLines = (items, indent, linePrefix) => {
      const lines = [];
      let line = [];
      let lineLen = (linePrefix === undefined ? indent.length : linePrefix.length) - 1;
      for (const part of items) {
        if (lineLen + 1 + part.length > textWidth && line.length > 0) {
          lines.push(indent + line.join(' '));
          line = [];
          lineLen = indent.length - 1;
        }
        line.push(part);
        lineLen += 1 + part.length;
      }
      if (line.length > 0) lines.push(indent + line.join(' '));
      if (linePrefix !== undefined && lines.length > 0) lines[0] = lines[0].slice(indent.length);
      return lines;
    };

    let lines;
    if (prefix.length + this.prog.length <= 0.75 * textWidth) {
      // Short prog: the first usage parts follow it on the same line.
      const indent = ' '.repeat(prefix.length + this.prog.length + 1);
      lines = parts.length > 0 ? getLines([this.prog, ...parts], indent, prefix) : [this.prog];
    } else {
      // Long prog: it gets a line of its own, parts are indented under it.
      const indent = ' '.repeat(prefix.length);
      lines = [this.prog, ...getLines(parts, indent)];
    }
    return `${prefix}${lines.join('\n')}\n\n`;
  }

  /** `HelpFormatter._get_actions_usage_parts` for a single optional. */
  _formatActionUsagePart(action) {
    const optionString = action.optionStrings[0];
    const part = action.nargs === 0 ? optionString : `${optionString} ${action.metavarText}`;
    return action.required ? part : `[${part}]`;
  }

  /** `HelpFormatter._format_action_invocation`. */
  _formatActionInvocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    const metavar = action.metavarText;
    return action.optionStrings.map((s) => `${s} ${metavar}`).join(', ');
  }

  /** `HelpFormatter._format_action` for one option row of the help body. */
  _formatAction(action, width, helpPosition) {
    const invocation = this._formatActionInvocation(action);
    const actionWidth = helpPosition - HELP_INDENT - 2;
    const helpWidth = Math.max(width - helpPosition, 11);
    const indent = ' '.repeat(HELP_INDENT);

    // No help text: the invocation is the whole row.
    if (!action.help) return `${indent}${invocation}\n`;

    let header;
    let indentFirst;
    if (invocation.length <= actionWidth) {
      header = indent + invocation.padEnd(actionWidth) + '  ';
      indentFirst = 0;
    } else {
      header = `${indent}${invocation}\n`;
      indentFirst = helpPosition;
    }

    const text = action.help.replace(WHITESPACE_MATCHER, ' ').trim();
    const helpLines = wrapText(text, helpWidth);
    let out = header + ' '.repeat(indentFirst) + helpLines[0] + '\n';
    for (const line of helpLines.slice(1)) out += ' '.repeat(helpPosition) + line + '\n';
    return out;
  }

  // -- output / termination -------------------------------------------------

  printUsage() {
    writeAllSync(1, this.formatUsage());
  }

  printHelp() {
    writeAllSync(1, this.formatHelp());
  }

  /** `ArgumentParser.exit()`. */
  exit(status = 0, message) {
    if (message) writeAllSync(2, message);
    process.exit(status);
  }

  /** `ArgumentParser.error()`: usage + one error line on stderr, then exit 2. */
  error(message) {
    writeAllSync(2, this.formatUsage());
    this.exit(EXIT_ARG_ERROR, `${this.prog}: error: ${message}\n`);
  }

  // -- parsing --------------------------------------------------------------

  /**
   * `ArgumentParser.parse_args()`. Prints help and exits 0 for `-h`/`--help`,
   * prints usage plus the error and exits 2 on any parse error.
   *
   * @param {string[]} [argv] defaults to `process.argv.slice(2)`.
   * @returns {Object} the namespace, e.g. `{key, iv, data1, data2}`.
   */
  parseArgs(argv = process.argv.slice(2)) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) this.error(`unrecognized arguments: ${extras.join(' ')}`);
    return namespace;
  }

  /** `ArgumentParser.parse_known_args()`. */
  parseKnownArgs(argv = process.argv.slice(2)) {
    const namespace = {};
    for (const action of this._actions) {
      if (action.default !== SUPPRESS) namespace[action.dest] = action.default;
    }
    try {
      return this._parseKnownArgs(argv, namespace);
    } catch (err) {
      if (err instanceof ExitParser) this.exit(err.status, err.stream);
      if (err instanceof ArgumentError) this.error(err.message);
      throw err;
    }
  }

  _parseKnownArgs(argStrings, namespace) {
    // -- Phase 1: classify every token before consuming anything. An
    // ambiguous abbreviation anywhere in argv therefore beats every other
    // error, including --help.
    const optionTuples = new Map();
    const pattern = [];
    let afterDoubleDash = false;
    for (let i = 0; i < argStrings.length; i += 1) {
      const argString = argStrings[i];
      if (afterDoubleDash) {
        // Everything past the first '--' is a plain argument, uninspected
        // (so a second '--' is an argument too).
        pattern.push('A');
      } else if (argString === '--') {
        afterDoubleDash = true;
        pattern.push('-');
      } else {
        const tuple = this._parseOptional(argString);
        if (tuple === null) pattern.push('A');
        else {
          optionTuples.set(i, tuple);
          pattern.push('O');
        }
      }
    }

    const seenActions = new Set();
    const extras = [];

    // -- Phase 2: consume left to right. No positionals are declared, so any
    // 'A' token not eaten as an option's value is an extra, in argv order.
    let index = 0;
    while (index < argStrings.length) {
      if (optionTuples.has(index)) {
        index = this._consumeOptional(
          index, argStrings, pattern, optionTuples, extras, namespace, seenActions,
        );
      } else {
        extras.push(argStrings[index]);
        index += 1;
      }
    }

    // -- Phase 3: required options, in declaration order.
    const missing = this._actions
      .filter((action) => action.required && !seenActions.has(action))
      .map((action) => action.canonicalName);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /**
   * `ArgumentParser._parse_optional`: classify one token.
   * @returns {null|{action: Action|null, optionString: string, sep: string|null,
   *                 explicitArg: string|null}}
   */
  _parseOptional(argString) {
    if (argString === '') return null;
    if (!PREFIX_CHARS.includes(argString[0])) return null;

    const exact = this._optionStringActions.get(argString);
    if (exact !== undefined) {
      return { action: exact, optionString: argString, sep: null, explicitArg: null };
    }

    // A lone '-' is a positional.
    if (argString.length === 1) return null;

    // '--opt=value': only the part before the first '=' is the option string.
    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const head = argString.slice(0, eq);
      const action = this._optionStringActions.get(head);
      if (action !== undefined) {
        return { action, optionString: head, sep: '=', explicitArg: argString.slice(eq + 1) };
      }
    }

    const tuples = this._getOptionTuples(argString);
    if (tuples.length > 1) {
      const names = tuples.map((t) => t.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${names}`);
    }
    if (tuples.length === 1) return tuples[0];

    // Looks like a negative number, and no option does: a positional.
    if (NEGATIVE_NUMBER_MATCHER.test(argString)) return null;
    // Contains a space: a positional.
    if (argString.includes(' ')) return null;

    // An unknown optional.
    return { action: null, optionString: argString, sep: null, explicitArg: null };
  }

  /** `ArgumentParser._get_option_tuples`: prefix-abbreviation candidates. */
  _getOptionTuples(argString) {
    const result = [];
    const eq = argString.indexOf('=');
    const optionPrefix = eq === -1 ? argString : argString.slice(0, eq);
    const sep = eq === -1 ? null : '=';
    const explicitArg = eq === -1 ? null : argString.slice(eq + 1);

    if (PREFIX_CHARS.includes(argString[1])) {
      // Long options are only ever split at the '='.
      for (const [optionString, action] of this._optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, sep, explicitArg });
        }
      }
    } else {
      // A single-character option may carry its argument attached.
      const shortPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this._optionStringActions) {
        if (optionString === shortPrefix) {
          result.push({ action, optionString, sep: '', explicitArg: shortExplicitArg });
        } else if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, sep, explicitArg });
        }
      }
    }
    return result;
  }

  /**
   * `ArgumentParser._parse_known_args.consume_optional`: take the option at
   * `startIndex` plus any options bundled into its tail, and return the index
   * just past everything consumed.
   */
  _consumeOptional(startIndex, argStrings, pattern, optionTuples, extras, namespace, seenActions) {
    let { action, optionString, sep, explicitArg } = optionTuples.get(startIndex);
    // Bundled actions are collected first and only run once the whole tail
    // parses, so e.g. `-h-x` errors instead of printing help.
    const actionTuples = [];
    let stop;

    for (;;) {
      if (action === null) {
        extras.push(argStrings[startIndex]);
        return startIndex + 1;
      }

      if (explicitArg !== null) {
        const argCount = this._matchArgument(action, 'A');
        if (argCount === 0 && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
          // A single-dash flag with a tail: try to read more flags out of it.
          if (sep || PREFIX_CHARS.includes(explicitArg[0])) {
            throw new ArgumentError(action, `ignored explicit argument ${pythonStrRepr(explicitArg)}`);
          }
          actionTuples.push([action, [], optionString]);
          const char = optionString[0];
          optionString = char + explicitArg[0];
          const next = this._optionStringActions.get(optionString);
          if (next !== undefined) {
            action = next;
            explicitArg = explicitArg.slice(1);
            if (explicitArg === '') {
              sep = null;
              explicitArg = null;
            } else if (explicitArg[0] === '=') {
              sep = '=';
              explicitArg = explicitArg.slice(1);
            } else {
              sep = '';
            }
          } else {
            // Unknown bundled flag: the rest of the tail becomes an extra.
            extras.push(char + explicitArg);
            stop = startIndex + 1;
            break;
          }
        } else if (argCount === 1) {
          stop = startIndex + 1;
          actionTuples.push([action, [explicitArg], optionString]);
          break;
        } else {
          throw new ArgumentError(action, `ignored explicit argument ${pythonStrRepr(explicitArg)}`);
        }
      } else {
        // The value must be the next token and must be a plain argument:
        // neither another option nor '--' can serve as one.
        const start = startIndex + 1;
        const argCount = this._matchArgument(action, pattern.slice(start).join(''));
        stop = start + argCount;
        actionTuples.push([action, argStrings.slice(start, stop), optionString]);
        break;
      }
    }

    for (const [pending, args, optStr] of actionTuples) {
      this._takeAction(pending, args, optStr, namespace, seenActions);
    }
    return stop;
  }

  /**
   * `ArgumentParser._match_argument`: how many of the classified tokens the
   * action consumes. `nargs=None` needs exactly one 'A'; `nargs=0` needs none.
   * (For optionals argparse strips '-' from the nargs pattern, so a '-'/'O'
   * token can never be swallowed as a value.)
   */
  _matchArgument(action, argStringsPattern) {
    if (action.nargs === 0) return 0;
    if (argStringsPattern.startsWith('A')) return 1;
    throw new ArgumentError(action, 'expected one argument');
  }

  /** `take_action`: mark the action seen and apply it. */
  _takeAction(action, argStrings, optionString, namespace, seenActions) {
    seenActions.add(action);
    if (action.isHelp) {
      // print_help() then parser.exit(): help wins over the required and
      // unrecognized checks, which run later.
      throw new ExitParser(0, undefined, this.printHelp());
    }
    const [argString] = argStrings;
    namespace[action.dest] = action.type === undefined ? argString : action.type(argString);
  }
}

export default { ArgumentParser };

