// Scratch driver: the argparse layer of test7.py, with the oracle's PROG so
// help/usage/error text can be diffed byte for byte. Not part of the deliverable.
import process from 'node:process';
import { ArgumentParser } from '../../output/lib/argparse.mjs';

const parser = new ArgumentParser({ prog: 'test7_executable' });
parser.addArgument('--key', { type: String, required: true });
parser.addArgument('--iv', { type: String, required: true });
parser.addArgument('--data1', { type: String, required: true });
parser.addArgument('--data2', { type: String, required: true });

const args = parser.parseArgs();
process.stdout.write(`PARSED ${JSON.stringify([args.key, args.iv, args.data1, args.data2])}\n`);

// Differential harness: run every argv vector against the frozen CPython
// oracle and against the ported argparse, and require identical observable
// behaviour. Scratch file, not part of the deliverable.
import process from 'node:process';
import { spawnSync } from 'node:child_process';

const ORACLE = '/workspace/dataset/test7_executable';
const DRIVER = '/workspace/verify/t-args-driver.mjs';
const K = '0123456789abcdef'; // 16 bytes
const FOUR = ['--key', K, '--iv', K, '--data1', K, '--data2', K];

function run(cmd, argv, env) {
  const res = spawnSync(cmd[0], [...cmd.slice(1), ...argv], {
    env: { ...process.env, ...env },
    encoding: 'buffer',
  });
  return {
    status: res.status,
    stdout: res.stdout.toString('utf8'),
    stderr: res.stderr.toString('utf8'),
  };
}

const show = (s) => JSON.stringify(s);

let pass = 0;
const failures = [];

function check(label, argv, env, expectValues) {
  const oracle = run([ORACLE], argv, env);
  const port = run([process.execPath, DRIVER], argv, env);
  const problems = [];

  if (oracle.status !== port.status) {
    problems.push(`exit: oracle=${oracle.status} port=${port.status}`);
  }

  const helpPath = oracle.status === 0 && oracle.stdout.startsWith('usage:');
  if (oracle.status === 2 || helpPath) {
    // Fully deterministic text on both streams.
    if (oracle.stdout !== port.stdout) {
      problems.push(`stdout:\n    oracle=${show(oracle.stdout)}\n    port  =${show(port.stdout)}`);
    }
    if (oracle.stderr !== port.stderr) {
      problems.push(`stderr:\n    oracle=${show(oracle.stderr)}\n    port  =${show(port.stderr)}`);
    }
  } else {
    // Oracle parsed cleanly (exit 0 with ciphertext, or exit 1 from the
    // cipher's ValueError). The port must reach the cipher stage too, so it
    // exits 0 from the driver, which only does the parsing half.
    if (port.status !== 0 || !port.stdout.startsWith('PARSED ') || port.stderr !== '') {
      problems.push(`expected a clean parse, got exit=${port.status} stdout=${show(port.stdout)} stderr=${show(port.stderr)}`);
    } else if (expectValues !== undefined) {
      const got = port.stdout.slice('PARSED '.length).trim();
      const want = JSON.stringify(expectValues);
      if (got !== want) problems.push(`values: want=${want} got=${got}`);
    }
  }

  if (problems.length === 0) pass += 1;
  else failures.push(`FAIL ${label}\n  argv=${show(argv)}${env ? ` env=${show(env)}` : ''}\n  ${problems.join('\n  ')}`);
}

// -- help / usage rendering, including terminal-width wrapping ---------------
for (const columns of [undefined, '20', '22', '24', '30', '40', '50', '60', '67', '69', '75', '76', '80', '120', '200', '0', 'abc']) {
  const env = columns === undefined ? { COLUMNS: undefined } : { COLUMNS: columns };
  check(`help COLUMNS=${columns}`, ['--help'], env);
  check(`usage-on-error COLUMNS=${columns}`, [], env);
}

// -- help forms and precedence ----------------------------------------------
const cases = [
  [['-h']], [['--help']], [['--h']], [['--he']], [['--hel']],
  [['-hh']], [['-h5']], [['-hx']], [['-h5x']], [['-h5=x']], [['-hkey']],
  [['-h-x']], [['-h=x']], [['-h=']], [['--h=x']], [['--help=x']], [['--help=']],
  [['-hh=x']], [['-h', '--help=q']], [['--help=q', '-h']],
  [["--help=it's"]], [['--help=say "hi"']], [['--help=both\'and"']], [['--help=tab\there']],
  [['--key', K, '-h']], [['-h', '--key', K]], [['--zzz', '-h']], [['-h', 'x']],
  [[...FOUR, '-h']], [[...FOUR, '--help', 'extra']],

  // -- missing required, only the missing ones, declaration order
  [[]], [['--key', K]], [['--iv', K]], [['--data2', K]],
  [['--key', K, '--iv', K]], [['--data1', K, '--key', K]], [['--data2', 'X', '--data1', 'Y']],
  [['--key', K, '--iv', K, '--data1', K]], [['--key', 'K']], [['--kéy', K]],
  [['--data1x']], [['--zzz']], [['foo', 'bar']], [['--']], [['--key=']],

  // -- unrecognized, argv order, single-space join
  [[...FOUR, '--zzz', '1']], [[...FOUR, '--zzz']], [[...FOUR, '--zzz', '--yyy']],
  [[...FOUR, '--zzz=1']], [[...FOUR, '--zzz=1', 'qqq']], [[...FOUR, 'foo']],
  [[...FOUR, 'foo', 'bar']], [[...FOUR, 'extra1', '--zzz', '5', 'extra2']],
  [['zfirst', ...FOUR, 'abar']], [[...FOUR, '-x']], [[...FOUR, '-xyz']],
  [[...FOUR, '-']], [[...FOUR, '---']], [[...FOUR, '']], [[...FOUR, '', '']],
  [[...FOUR, 'héllo→']], [['--key', K, 'foo', 'bar', '--iv', K, '--data1', K, '--data2', K]],
  [[...FOUR, '-x=1']],

  // -- abbreviation: accepted
  [['--k', K, '--iv', K, '--data1', K, '--data2', K], undefined, [K, K, K, K]],
  [['--ke', K, '--i', K, '--data1', K, '--data2', K], undefined, [K, K, K, K]],
  [[`--ke=${K}`, '--iv', K, '--data1', K, '--data2', K], undefined, [K, K, K, K]],
  [['--data1', K, '--data2', K, '--key', K, '--iv', K], undefined, [K, K, K, K]],

  // -- abbreviation: ambiguous (wins over everything)
  [['--d']], [['--dat']], [['--data']], [['--da']], [[`--da=${K}`]],
  [['--=']], [['--=x']], [['--d', '--da']], [['--da', '--d']],
  [['-h', '--d']], [['--d', '-h']], [['--key', '--d']],
  [[...FOUR, '--zzz', '1', '--d']],

  // -- '=' form and empty values
  [[`--key=${K}`, `--iv=${K}`, `--data1=${K}`, `--data2=${K}`], undefined, [K, K, K, K]],
  [[`--key=${K}`, '--iv', K, `--data1=${K}`, '--data2', K], undefined, [K, K, K, K]],
  [['--key=a=b', '--iv', K, '--data1', K, '--data2', K], undefined, ['a=b', K, K, K]],
  [['--key=', '--iv', K, '--data1', K, '--data2', K], undefined, ['', K, K, K]],
  [['--key', '', '--iv', K, '--data1', K, '--data2', K], undefined, ['', K, K, K]],
  [['--key', K, '--iv=', '--data1', K, '--data2', K], undefined, [K, '', K, K]],
  [['--key', K, '--iv', K, '--data1=', '--data2', K], undefined, [K, K, '', K]],
  [['--key', K, '--iv', K, '--data1', K, '--data2='], undefined, [K, K, K, '']],

  // -- repeated options: last wins
  [['--key', 'AAAAAAAAAAAAAAAA', '--key', K, '--iv', K, '--data1', K, '--data2', K], undefined, [K, K, K, K]],
  [['--key', K, '--data1', K, '--data2', K, `--iv=${K}`, `--key=${K}`], undefined, [K, K, K, K]],

  // -- missing value
  [['--key']], [['--key', '--iv']], [['--key', '--', K]], [['--key', K, '--iv']],
  [['--key', K, '--iv', K, '--data1', K, '--i']], [[...FOUR.slice(0, 6), '--data2']],
  [['--data2', '--key', K, '--iv', K, '--data1', K]],

  // -- values beginning with '-'
  [['--key', '-5', '--iv', K, '--data1', K, '--data2', K], undefined, ['-5', K, K, K]],
  [['--key', '-12345678901234', '--iv', K, '--data1', K, '--data2', K], undefined, ['-12345678901234', K, K, K]],
  [['--key', '-123456789012345', '--iv', K, '--data1', K, '--data2', K], undefined, ['-123456789012345', K, K, K]],
  [['--key', '-1.5', '--iv', K, '--data1', K, '--data2', K], undefined, ['-1.5', K, K, K]],
  [['--key', '-.5', '--iv', K, '--data1', K, '--data2', K], undefined, ['-.5', K, K, K]],
  [['--key', '-', '--iv', K, '--data1', K, '--data2', K], undefined, ['-', K, K, K]],
  [['--key', '-a b', '--iv', K, '--data1', K, '--data2', K], undefined, ['-a b', K, K, K]],
  [['--key', '- x', '--iv', K, '--data1', K, '--data2', K], undefined, ['- x', K, K, K]],
  [['--key', ' -5', '--iv', K, '--data1', K, '--data2', K], undefined, [' -5', K, K, K]],
  [['--key', '-٥', '--iv', K, '--data1', K, '--data2', K], undefined, ['-٥', K, K, K]],
  [['--key', '-5٥', '--iv', K, '--data1', K, '--data2', K], undefined, ['-5٥', K, K, K]],
  [['--key', '-5\n', '--iv', K, '--data1', K, '--data2', K], undefined, ['-5\n', K, K, K]],
  [['--key', '-5\n\n']], [['--key', '-5\nx']],
  [['--key', '-X']], [['--key', '-5a']], [['--key', '-5.5.5']],
  [['--key=-X', '--iv', K, '--data1', K, '--data2', K], undefined, ['-X', K, K, K]],

  // -- '--' end of options (never stripped, never a value)
  [[...FOUR, '--']], [[...FOUR, '--', '--']], [[...FOUR, '--', 'foo']],
  [[...FOUR, '--', '--', 'foo']], [[...FOUR, '--', '--key', 'X']], [[...FOUR, '--', '--d']],
  [['--', ...FOUR]], [['--key', K, '--iv', K, '--data1', K, '--', '--data2', K]],

  // -- single dash is never an abbreviation
  [['-k']], [['-key']], [['-k', K]],

  // -- happy path with the mission's key material
  [['--key', '6G!I:]M.SYzm[v9[', '--iv', '*ANz^hUTfAHTf!he',
    '--data1', '^Roq|2L=X{7CRJh{', '--data2', 'Gr.c8LH=f{xn_V0L'],
    undefined, ['6G!I:]M.SYzm[v9[', '*ANz^hUTfAHTf!he', '^Roq|2L=X{7CRJh{', 'Gr.c8LH=f{xn_V0L']],
  // -- multi-byte UTF-8 values survive verbatim
  [['--key', 'ccccccccccccccé', '--iv', K, '--data1', 'ccccccccccccccé', '--data2', K],
    undefined, ['ccccccccccccccé', K, 'ccccccccccccccé', K]],
];

for (const [argv, env, expectValues] of cases) {
  check(argv.join(' ') || '(no args)', argv, env, expectValues);
}

process.stdout.write(`\n${pass} passed, ${failures.length} failed (of ${pass + failures.length})\n`);
if (failures.length > 0) {
  process.stdout.write(`\n${failures.join('\n\n')}\n`);
  process.exitCode = 1;
}

