const POOL = [
  '--key', '--iv', '--data1', '--data2', '--k', '--ke', '--i', '--d', '--da',
  '--data', '-h', '--help', '--h', '--', '-', '-x', '-k', '-hh', '-h5', '-hx',
  '-h=x', '-h-x', 'foo', '', '=', '--=', '--key=', `--key=${K}`, '--iv=',
