  '-٥', K, '--zzz', '--zzz=1', '---', 'héllo→', '-5\n',
];
// mulberry32: a fixed seed keeps the run reproducible.
let seed = 0x2f6e2b1;
const rand = (n) => {
  seed = (seed + 0x6d2b79f5) | 0;
  let t = seed;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return (((t ^ (t >>> 14)) >>> 0) / 4294967296 * n) | 0;
};
const fuzzCount = Number.parseInt(process.argv[2] === undefined ? '400' : process.argv[2], 10);
for (let i = 0; i < fuzzCount; i += 1) {
  const argv = [];
  for (let j = rand(7); j > 0; j -= 1) argv.push(POOL[rand(POOL.length)]);
  check(`fuzz#${i}`, argv, undefined, undefined);
}

